193	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
194	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
195	            }
196	        }
197	        // The owner's telephone and email are now in their canonical, stored form.
198	        // The household id is deterministic: owners with the same normalized last name and
199	        // postcode share it automatically. Assign it unconditionally so the membership-level
200	        // ceiling can key off it; it no longer participates in duplicate detection, which now
201	        // rests solely on the identity key below.
202	        owner.setHouseholdId(householdResolver.householdId(owner));
203	        // Duplicate detection is the single identity key: a candidate is rejected only when its
204	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
205	        // collides with a non-deleted owner's. Two people sharing a household with different
206	        // telephones therefore derive different keys and are both admitted; the second is instead
207	        // flagged as a possible duplicate by the soft-match rule below.
208	        if (isDuplicateOwner(owner)) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
212	        long ownersInCity = this.clinicService.findAllOwners().stream()
213	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
214	            .count();
215	        if (ownersInCity >= 50) {
216	            return new ResponseEntity<>(HttpStatus.CONFLICT);
217	        }
218	        owner.setCustomerCode(customerCode(owner));
219	        owner.setNamesakeCount(namesakeCount(owner));
220	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
221	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
222	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
223	        // identityKey may still differ from an existing owner's while their last names sound alike
224	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
225	        // under a different telephone or email. When it does, it is created but flagged as a
226	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
227	        // is recorded.
228	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
229	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
230	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
231	        this.clinicService.saveOwner(owner);
232	        if (key != null) {
233	            idempotencyKeys.put(key, owner.getId());
234	        }
235	        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
236	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
241	
242	    /**
243	     * The owner's postal address in the single canonical form under which it is stored, or
244	     * {@code null} when the owner supplies no usable address. An owner may supply its address
245	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
246	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
247	     *
248	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
249	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
250	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
251	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
252	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
253	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
254	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
255	     * the caller can reject the request with 400.
256	     *
257	     * <p>This is the single point at which an owner's address is resolved and normalized on
258	     * create, so every rule keyed on the stored address reads the one value produced here.
259	     *
260	     * @param owner the owner about to be created
261	     * @return the canonical stored address, or {@code null} when the owner supplies none
262	     */
263	    private String normalizedAddress(Owner owner) {
264	        String rawLine1 = owner.getAddressLine1();
265	        if (rawLine1 != null && !rawLine1.isBlank()) {
266	            String line1 = addressNormalizer.normalize(rawLine1);
267	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
268	            owner.setAddressLine1(line1);
269	            owner.setAddressLine2(line2.isBlank() ? null : line2);
270	            return line2.isBlank() ? line1 : line1 + " " + line2;
271	        }
272	        owner.setAddressLine1(null);
273	        owner.setAddressLine2(null);
274	        String address = addressNormalizer.normalize(owner.getAddress());
275	        return address.isBlank() ? null : address;
276	    }
277	
278	    /**
279	     * Whether {@code candidate} collides with an already-registered owner under the single
280	     * identity rule enforced on create. This is the one point at which a new owner is
281	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
282	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
283	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
284	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
285	     * existing owner's; because the telephone is part of the key, two people sharing a household
286	     * (a like-sounding last name and postcode) with different telephones have different
287	     * identityKeys and are both allowed.
288	     *
289	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
290	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
291	     * genuinely the same identity.
292	     *
293	     * @param candidate the fully-normalized owner about to be created
294	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
295	     */
296	    private boolean isDuplicateOwner(Owner candidate) {
297	        String identityKey = OwnerMapper.identityKey(candidate);
298	        return this.clinicService.findAllOwners().stream()
299	            .filter(existing -> !existing.isDeleted())
300	            .map(OwnerMapper::identityKey)
301	            .anyMatch(identityKey::equals);
302	    }
303	
304	    /**
305	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
306	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
307	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
308	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
309	     * of the same person under a different telephone or email. Both must supply a postcode for a
310	     * match to be possible; when several existing owners qualify the lowest id is returned so the
311	     * result is deterministic.
312	     *
313	     * @param candidate the fully-normalized owner about to be created
314	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
315	     */
316	    private Integer possibleDuplicateOf(Owner candidate) {
317	        String postcode = candidate.getPostcode();
318	        if (postcode == null || postcode.isBlank()) {
319	            return null;
320	        }
321	        String identityKey = OwnerMapper.identityKey(candidate);
322	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
323	        return this.clinicService.findAllOwners().stream()
324	            .filter(existing -> !existing.isDeleted()
325	                && !identityKey.equals(OwnerMapper.identityKey(existing))
326	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
327	                && postcode.equals(existing.getPostcode()))
328	            .map(Owner::getId)
329	            .filter(java.util.Objects::nonNull)
330	            .min(Integer::compareTo)
331	            .orElse(null);
332	    }
333	
334	    /**
335	     * Build the customer code assigned to {@code owner} on create, formatted
336	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
337	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
338	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
339	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
340	     *
341	     * <p>When the computed code collides with an already-registered owner's customerCode it is
342	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
343	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
344	     */
345	    private String customerCode(Owner owner) {
346	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
347	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
348	        String base = region + "-" + hash8;
349	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
350	            .map(Owner::getCustomerCode)
351	            .filter(java.util.Objects::nonNull)
352	            .collect(java.util.stream.Collectors.toSet());
353	        if (!existing.contains(base)) {
354	            return base;
355	        }
356	        int n = 2;
357	        while (existing.contains(base + "-" + n)) {
358	            n++;
359	        }
360	        return base + "-" + n;
361	    }
362	
363	    /**
364	     * The number of existing owners that share {@code owner}'s firstName and lastName,
365	     * compared case-insensitively. The candidate is not yet stored at the point this is
366	     * assigned, so it does not count itself. This is the value stored as the owner's
367	     * namesakeCount on create.
368	     */
369	    private int namesakeCount(Owner owner) {
370	        return (int) this.clinicService.findAllOwners().stream()
371	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
372	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
373	            .count();
374	    }
375	
376	    /** Fixed list of public holidays that a registration date must roll past. */
377	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
378	        LocalDate.of(2026, 1, 1),
379	        LocalDate.of(2026, 1, 26),
380	        LocalDate.of(2026, 4, 25),
381	        LocalDate.of(2026, 12, 25),
382	        LocalDate.of(2026, 12, 28));
383	
384	    /**
385	     * Roll a registration date forward to the next business day: a Saturday, Sunday
386	     * or listed public holiday advances one day at a time until it lands on a weekday
387	     * that is not a public holiday. A plain weekday is returned unchanged.
388	     */
389	    private static LocalDate toBusinessDay(LocalDate date) {
390	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
391	            date = date.plusDays(1);
392	        }
393	        return date;
394	    }
395	
396	    private static boolean isWeekend(LocalDate date) {
397	        return switch (date.getDayOfWeek()) {
398	            case SATURDAY, SUNDAY -> true;
399	            default -> false;
400	        };
401	    }
402	
403	    /**
404	     * Build the membership number assigned on create, formatted
405	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
406	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
407	     * 'NSW-1A2B3C4D-M26'.
408	     */
409	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
410	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
411	        return customerCode + "-M" + yy;
412	    }
413	}
